@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def enter_site_setup_tolerance(tolerance: str) -> None:
    """Locates the D and I - Site Setup Form > then types in a given tolerance value in the Tolerance textbox/dropdown.

    :param str tolerance: Given tolerance string to be entered
    """
    if __find_site_setup_form_window():
        CommonActions.type_in_textfield(DandI.siteSetup_Form_Tolerance_TextBox, tolerance)
        CommonActions.left_click_object(DandI.siteSetup_Form_Tolerance_TextBox)

