@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def enter_site_setup_accessory(accessory: str) -> None:
    """Locates the D and I - Site Setup Form > then types in a given accessory value in the first Accessory textbox/dropdown.

    :param str accessory: Given accessory string to be entered
    """
