@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def enter_site_setup_index_accessory(indexPosition: int, indexValue: str) -> None:
    """Locates the D and I - Site Setup Form > then types in a given index value for the specified index textbox.

    :param str indexPosition: Index field to be selected based on the position, starting from 1
    :param str indexValue: Index string value to be entered into the index field
    """
    if __find_site_setup_form_window():
        accessory_index_field = {"container": DandI.siteSetup_Form_Accessories_Item_Container, "name": "idxDevice" + str(indexPosition)}
        CommonActions.left_click_object(accessory_index_field)
        CommonActions.press_key_sequence(indexValue)

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def type_site_setup_instructions(setupInstructions: str) -> None:
    """Types a given setupInstruction string into the Setup Instructions textbox of the Site Setup UI

    :param setupInstructions: String value to be entered into the Setup Instructions textbox
    :type setupInstructions: str
    """
    if __find_site_setup_form_window():
        CommonActions.type_in_textfield(DandI.siteSetup_Setup_Instructions_Textbox, setupInstructions)

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def enter_prescribed_offset_x_value(xValue: float) -> None:
    """Locates the Site Setup form window > clears the prescribed offset X value textbox > enters in the given xValue int value as a string.

    :param xValue: Integar value that will be entered as a string into the Prescribed Offset X Value textbox
    :type xValue: float
    """
    if __find_site_setup_form_window():
        CommonActions.left_click_object(DandI.siteSetup_Prescribed_Offset_X_Value_Textbox)
        CommonActions.press_key_sequence("<Ctrl+Delete>")
        CommonActions.type_in_textfield(DandI.siteSetup_Prescribed_Offset_X_Value_Textbox, str(xValue))

