@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def click_site_setup_approve() -> None:
    """Locates the D and I - Site Setup Form > then clicks the Approve button.
    """
    if __find_site_setup_form_window():
        CommonActions.left_click_object(DandI.siteSetup_Form_Approve_Button)

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def enter_site_setup_approval_password(password: str, waitForSiteSetupToClose: bool = False) -> None:
    """Locates the D and I - Site Setup Approval dialog > then types in a given password value in the password textbox.

    :param str password: Given password string to be entered
    :param bool waitForSiteSetupToClose: If True, waits for the Site Setup window to close after entering the password
    """
    CommonActions.find_object(DandI.siteSetup_Approval_Window)
    CommonActions.type_in_textfield(DandI.siteSetup_Approval_Password_TextBox, password)
    if waitForSiteSetupToClose:
        CommonActions.wait_for_object_to_disappear(DandI.siteSetup_Main_Window, timeoutInSecs=5)

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def click_site_setup_approval_ok_button() -> None:
    """Locates the D and I - Site Setup Approval dialog > then clicks the OK button.
    """
    CommonActions.find_object(DandI.siteSetup_Approval_Window)
    CommonActions.left_click_object(DandI.siteSetup_Approval_OK_Button)